-- 0016_device_registered_at — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- Reconciliation (Vlad, 4 Nov): a device registered in OCS (by hand or import) versus one that only came from the
-- device platform sync. registered_at is when someone registered it in OCS; null means the platform brought it in
-- and nobody has confirmed it by SN yet. Every device before this migration was registered by hand.
ALTER TABLE device ADD COLUMN registered_at timestamptz;
UPDATE device SET registered_at = created_at;
COMMENT ON COLUMN device.registered_at IS 'When registered in OCS by SN (manual or import); null: only from the platform';
